/*
 * A029798  Squares k such that k and k^(3/2) have the same set of digits.
 * https://oeis.org/A029798
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = m² where m² and m³ have the same set of decimal digits
 * Range:     u8 n <= 2, u16 n <= 3, u32 n <= 8, u64 n <= 22, u128 n <= 22,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by scanning integers m = 0,1,2,… and selecting
 * the squares whose digit mask equals that of the cube. */

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>

/* Return a bitmask of the decimal digits present in x (0‑9). */
static uint16_t digit_mask(seq_t x)
{
    uint16_t mask = 0;
    if (x == (seq_t)0)                /* 0 has only digit 0 */
        return 1 << 0;
    while (x != (seq_t)0) {
        seq_t d = x % (seq_t)10;       /* 0 … 9 */
        mask |= (uint16_t)(1U << (unsigned int)d);
        x /= (seq_t)10;
    }
    return mask;
}

/* seq_t a(idx_t n) – return the n‑th term of the sequence (n ≥ 1). */
seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;                 /* undefined for offset 1, but safe */

    idx_t found = 0;                     /* number of matches seen */
    for (idx_t m = 0; ; ++m) {
        seq_t square, cube;

        /* Compute m² and m³ safely, avoiding overflow on 64‑bit builds. */
        if (sizeof(seq_t) <= 8) {
            unsigned __int128 sq128 = (unsigned __int128)m * m;
            if (sq128 > (unsigned __int128)~(seq_t)0)
                break;                  /* further squares will overflow */
            unsigned __int128 cu128 = sq128 * m;
            square = (seq_t)sq128;
            cube   = (seq_t)cu128;
        } else {
            seq_t mseq = (seq_t)m;
            square = mseq * mseq;       /* m² */
            cube   = square * mseq;     /* m³ */
        }

        if (digit_mask(square) == digit_mask(cube)) {
            ++found;
            if (found == n)
                return square;
        }
    }

    /* If we ran out of representable squares, return 0 as a safe fallback. */
    return (seq_t)0;
}
